function parseCompactNumber(value){let s=String(value??'').trim().toLowerCase().replace(/\s+/g,''),mult=1;if(!s)return 0;let suffixes=[[/bilh(?:ão|ao|ões|oes)$|bi$|b$/,1e9],[/milh(?:ão|ao|ões|oes)$|mi$|m$/,1e6],[/mil$|k$/,1e3]];for(let [rx,n] of suffixes)if(rx.test(s)){mult=n;s=s.replace(rx,'');break}if(s.includes(','))s=s.replace(/\./g,'').replace(',','.');else if(/^\d{1,3}(\.\d{3})+$/.test(s))s=s.replace(/\./g,'');s=s.replace(/[^\d.-]/g,'');return(Math.max(0,Number(s)||0))*mult}
