function applyAccent(){let accent=lifetimeActive?(state.profile.accent||'#32ff7e'):'#32ff7e',hex=accent.replace('#','');if(!/^[0-9a-f]{6}$/i.test(hex))accent='#32ff7e';let r=parseInt(accent.slice(1,3),16),g=parseInt(accent.slice(3,5),16),b=parseInt(accent.slice(5,7),16),root=document.documentElement;root.style.setProperty('--green',accent);root.style.setProperty('--greenfade',`rgba(${r},${g},${b},.11)`)}
