function recordPortfolioSnapshot(){state.portfolioHistory=Array.isArray(state.portfolioHistory)?state.portfolioHistory:[];let t=totals(),value=t.current,invested=t.invested,date=today(),found=state.portfolioHistory.find(x=>x.date===date);if(found){found.value=value;found.invested=invested}else state.portfolioHistory.push({date,value,invested});state.portfolioHistory=state.portfolioHistory.slice(-730)}
function goalsSavedAt(key=today()){return state.goals.reduce((total,goal)=>{let deposits=goal.deposits||[],depositedTotal=deposits.reduce((sum,item)=>sum+(+item.amount||0),0),base=Math.max(0,(+goal.current||0)-depositedTotal),created=(goal.createdAt||goal.date||today()).slice(0,10),value=created<=key?base:0;value+=deposits.filter(item=>(item.createdAt||'').slice(0,10)<=key).reduce((sum,item)=>sum+(+item.amount||0),0);return total+value},0)}
function totals(){let income=state.transactions.filter(x=>x.type==='income').reduce((a,x)=>a+(+x.amount||0),0),expense=state.transactions.filter(x=>x.type!=='income').reduce((a,x)=>a+(+x.amount||0),0),invested=state.investments.reduce((a,x)=>a+(+x.quantity||0)*(+x.averagePrice||0),0),current=state.investments.reduce((a,x)=>a+(+x.quantity||0)*(+x.currentPrice||+x.averagePrice||0),0),goalSaved=goalsSavedAt();return{income,expense,invested,current,goalSaved,balance:income-expense,wealth:income-expense+current+goalSaved}}

