function renderNextEvent(){let box=document.getElementById('nextEvent');if(!box)return;let now=new Date(),next=[];for(let offset=0;offset<=400&&!next.length;offset++){let d=new Date(now.getFullYear(),now.getMonth(),now.getDate()+offset),date=dateKey(d);next=state.events.filter(x=>eventOccursOn(x,date)).map(x=>({...x,occurrenceDate:date,when:new Date(`${date}T${x.time||'23:59'}`)})).filter(x=>x.when>=now).sort((a,b)=>a.when-b.when)}let x=next[0];if(!x){box.classList.add('empty-event');box.innerHTML='<i>◷</i><div><small>PRÓXIMO COMPROMISSO</small><b>Nenhum compromisso agendado</b><em>Adicione um evento na Agenda.</em></div>';return}box.classList.remove('empty-event');let date=x.when.toLocaleDateString('pt-BR',{day:'2-digit',month:'short'}).replace('.',''),time=x.time?` às ${x.time}`:'';box.innerHTML=`<i>◷</i><div><small>PRÓXIMO COMPROMISSO</small><b>${safe(x.name)}</b><em>${date}${time}${x.location?' • '+safe(x.location):''}</em></div><button data-action="edit" data-entity="events" data-id="${x.id}" aria-label="Editar compromisso">↗</button>`}
