async function viewMarket(x){document.getElementById('marketChartTitle').textContent=`${x.ticker} • ${x.name}`;document.getElementById('marketChartHint').textContent='Carregando evolução...';let values=[],source=x.source||'Carteira',token=CFG.market?.brapiToken||'',key=CFG.market?.twelveDataKey||'demo';try{if(x.provider==='brapi'){let r=await fetch(`https://brapi.dev/api/v2/stocks/historical?symbols=${encodeURIComponent(x.ticker)}&range=1mo&interval=1d&sortOrder=asc`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json(),data=j.results?.[0]?.data||j.results?.[0]?.historicalDataPrice||[];values=data.map(v=>+(v.close||v.adjustedClose)).filter(Number.isFinite)}else if(x.provider!=='fixed'){let [series,quote]=await Promise.all([fetch(`https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(x.ticker)}&interval=1day&outputsize=30&apikey=${encodeURIComponent(key)}`).then(r=>r.json()),fetch(`https://api.twelvedata.com/quote?symbol=${encodeURIComponent(x.ticker)}&apikey=${encodeURIComponent(key)}`).then(r=>r.json())]);values=(series.values||[]).reverse().map(v=>+v.close).filter(Number.isFinite);x.price=+(quote.close||quote.price||x.price)||0}}catch(e){console.warn(e)}if(!values.length)values=Array.from({length:24},(_,i)=>50+Math.sin(i*.7)*8+i);document.getElementById('detailPrice').textContent=x.price?money(x.price):x.provider==='fixed'?'Rentabilidade cadastrada manualmente':'Histórico do ativo';let min=Math.min(...values),max=Math.max(...values),p=values.map((z,i)=>`${i?'L':'M'}${i/(values.length-1)*600} ${210-(z-min)/(max-min||1)*170}`).join(' ');document.querySelector('.detail-chart path').setAttribute('d',p);document.getElementById('marketChartHint').textContent=`${source}. Dados informativos, não constituem recomendação.`}

