start.onclick=()=>{if(ticker){clearInterval(ticker);ticker=null;document.body.classList.remove('focus-running');logFocusProgress();start.textContent='▶ Continuar sessão';toast('Sessão pausada',`${formatFocus((total-left)/60)} focados até agora.`);return}start.textContent='Pausar sessão';document.body.classList.add('focus-running');ticker=setInterval(()=>{left--;rt();if(left<=0){clearInterval(ticker);ticker=null;document.body.classList.remove('focus-running');logFocusProgress();awardXP(`focus:${today()}:${state.focusSessions.length}`,50);writeLocalState();scheduleCloudSave();render();toast('Sessão concluída!','Tempo contabilizado e +50 XP para sua jornada.');left=total;loggedElapsed=0;rt();start.textContent='Iniciar sessão'}},1000)};
const ambient={ctx:null,master:null,nodes:[],timers:[],mode:null};
const soundNames={rain:'Chuva',forest:'Floresta',lofi:'Lo-fi',white:'Ruído branco'};
function stopAmbient(update=true){ambient.timers.forEach(clearInterval);ambient.timers=[];ambient.nodes.forEach(n=>{try{n.stop?.()}catch{}try{n.disconnect?.()}catch{}});ambient.nodes=[];if(ambient.ctx){ambient.ctx.close().catch(()=>{});ambient.ctx=null}ambient.master=null;ambient.mode=null;document.querySelectorAll('[data-sound]').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false')});if(update)document.getElementById('soundStatus').textContent='Som pausado. Escolha um ambiente para continuar.'}
function makeNoise(ctx,seconds=3){let buffer=ctx.createBuffer(2,ctx.sampleRate*seconds,ctx.sampleRate);for(let c=0;c<2;c++){let data=buffer.getChannelData(c),last=0;for(let i=0;i<data.length;i++){let white=Math.random()*2-1;last=(last+.025*white)/1.025;data[i]=white*.55+last*1.7}}return buffer}
function addNoise(ctx,kind){let source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=makeNoise(ctx);source.loop=true;if(kind==='rain'){filter.type='highpass';filter.frequency.value=650;gain.gain.value=.18}else if(kind==='forest'){filter.type='lowpass';filter.frequency.value=950;gain.gain.value=.07}else{filter.type='allpass';gain.gain.value=.085}source.connect(filter).connect(gain).connect(ambient.master);source.start();ambient.nodes.push(source,filter,gain)}
function forestChirp(ctx){let osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.type='sine';osc.frequency.setValueAtTime(1200+Math.random()*700,now);osc.frequency.exponentialRampToValueAtTime(2300+Math.random()*900,now+.14);gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.055,now+.025);gain.gain.exponentialRampToValueAtTime(.001,now+.32);osc.connect(gain).connect(ambient.master);osc.start(now);osc.stop(now+.35);ambient.nodes.push(osc,gain)}
function startLofi(ctx){let chord=0,progressions=[[110,164.81,220],[130.81,196,261.63],[98,146.83,196],[123.47,185,246.94]],voices=progressions[0].map((freq,i)=>{let osc=ctx.createOscillator(),gain=ctx.createGain(),filter=ctx.createBiquadFilter();osc.type=i?'sine':'triangle';osc.frequency.value=freq;filter.type='lowpass';filter.frequency.value=900;gain.gain.value=i?.035:.05;osc.connect(filter).connect(gain).connect(ambient.master);osc.start();ambient.nodes.push(osc,filter,gain);return osc});let change=()=>{let notes=progressions[chord++%progressions.length],now=ctx.currentTime;voices.forEach((osc,i)=>osc.frequency.exponentialRampToValueAtTime(notes[i],now+.7))};change();ambient.timers.push(setInterval(change,4000));let kick=()=>{let osc=ctx.createOscillator(),gain=ctx.createGain(),now=ctx.currentTime;osc.frequency.setValueAtTime(90,now);osc.frequency.exponentialRampToValueAtTime(46,now+.18);gain.gain.setValueAtTime(.12,now);gain.gain.exponentialRampToValueAtTime(.001,now+.22);osc.connect(gain).connect(ambient.master);osc.start();osc.stop(now+.24);ambient.nodes.push(osc,gain)};ambient.timers.push(setInterval(kick,1000));addNoise(ctx,'forest')}
function playAmbient(mode,button){if(ambient.mode===mode){stopAmbient();return}stopAmbient(false);let AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext){document.getElementById('soundStatus').textContent='Seu navegador não oferece suporte a áudio ambiente.';return}let ctx=new AudioContext();ambient.ctx=ctx;ambient.master=ctx.createGain();ambient.master.gain.value=(+document.getElementById('ambientVolume').value||32)/100;ambient.master.connect(ctx.destination);ambient.nodes.push(ambient.master);ambient.mode=mode;if(mode==='lofi')startLofi(ctx);else{addNoise(ctx,mode);if(mode==='forest'){forestChirp(ctx);ambient.timers.push(setInterval(()=>forestChirp(ctx),1800+Math.random()*1800))}}button.classList.add('active');button.setAttribute('aria-pressed','true');document.getElementById('soundStatus').textContent=`Tocando: ${soundNames[mode]} • clique novamente para pausar.`;ctx.resume()}
document.querySelectorAll('[data-sound]').forEach(button=>button.onclick=()=>playAmbient(button.dataset.sound,button));
document.getElementById('ambientVolume').oninput=e=>{if(ambient.master&&ambient.ctx)ambient.master.gain.setTargetAtTime(+e.target.value/100,ambient.ctx.currentTime,.04)};
function playlistEmbed(url){try{let parsed=new URL(url),host=parsed.hostname.replace(/^www\./,'');if(host==='open.spotify.com'){let [type,key]=parsed.pathname.split('/').filter(Boolean);if(['playlist','album','track','episode','show'].includes(type)&&key)return`https://open.spotify.com/embed/${type}/${encodeURIComponent(key)}`}if(host==='youtu.be'){let key=parsed.pathname.split('/').filter(Boolean)[0];if(key)return`https://www.youtube.com/embed/${encodeURIComponent(key)}?autoplay=1`}if(host.endsWith('youtube.com')){let list=parsed.searchParams.get('list'),video=parsed.searchParams.get('v');if(list)return`https://www.youtube.com/embed/videoseries?list=${encodeURIComponent(list)}&autoplay=1`;if(video)return`https://www.youtube.com/embed/${encodeURIComponent(video)}?autoplay=1`}}catch{}return''}
document.getElementById('playPlaylist').onclick=()=>{if(!lifetimeActive){showPremiumGate('Playlist personalizada','Conecte uma playlist do Spotify ou YouTube ao Modo Foco com o LUAR Vitalício.');return}let input=document.getElementById('playlistUrl'),src=playlistEmbed(input.value.trim());if(!src){toast('Link não reconhecido','Cole um link de playlist, álbum ou faixa do Spotify ou YouTube.');return}state.profile.playlistUrl=input.value.trim();writeLocalState();scheduleCloudSave();document.getElementById('customPlayer').innerHTML=`<iframe src="${safe(src)}" title="Playlist do modo foco" allow="autoplay; encrypted-media; picture-in-picture" loading="lazy"></iframe>`};

