const supabaseCfg=window.LUAR_CONFIG?.supabase||{},supabaseClient=window.supabase&&supabaseCfg.url&&supabaseCfg.anonKey?window.supabase.createClient(supabaseCfg.url,supabaseCfg.anonKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}):null;
function stateHasContent(data){return ['transactions','tasks','habits','goals','investments','events','moods','notes','focusSessions'].some(key=>Array.isArray(data?.[key])&&data[key].length)}
function applyAccountState(data){let next={...structuredClone(EMPTY),...(data||{})};next.profile={...structuredClone(EMPTY.profile),...(data?.profile||{})};['transactions','tasks','habits','goals','investments','events','moods','notes','focusSessions','portfolioHistory'].forEach(key=>next[key]=Array.isArray(next[key])?next[key]:[]);next.profile.xpClaims=next.profile.xpClaims&&typeof next.profile.xpClaims==='object'?next.profile.xpClaims:{};next.habits.forEach(h=>{h.history=Array.isArray(h.history)?h.history:[];h.xpDates=Array.isArray(h.xpDates)?h.xpDates:[];h.createdAt=h.createdAt||new Date().toISOString()});next.tasks.forEach(t=>{t.status=t.completed?'completed':t.status==='progress'?'progress':'todo';if(typeof t.xpAwarded!=='boolean')t.xpAwarded=!!t.completed});next.goals.forEach(g=>{g.deposits=Array.isArray(g.deposits)?g.deposits:[];g.emoji=g.emoji||'🎯'});next.notes.forEach(n=>{n.emoji=n.emoji||'📝';n.color=n.color||'#32ff7e'});state=next}
function scheduleCloudSave(){if(!currentUser||!supabaseClient||!lifetimeActive)return;clearTimeout(cloudSaveTimer);cloudSaveTimer=setTimeout(pushCloudState,900)}
async function pushCloudState(){if(!currentUser||!supabaseClient||!lifetimeActive)return false;let updatedAt=new Date().toISOString(),metadata={...(currentUser.user_metadata||{}),luar_state:state,luar_updated_at:updatedAt};let{data,error}=await supabaseClient.auth.updateUser({data:metadata});if(!error&&data.user){currentUser=data.user;return true}if(error)console.warn('LUAR cloud save:',error.message);return false}
async function sessionHeaders(){let{data}=await supabaseClient.auth.getSession(),token=data.session?.access_token;if(!token)throw new Error('Sua sessão expirou. Entre novamente.');return{'Content-Type':'application/json',Authorization:`Bearer ${token}`}}
async function verifyLifetimeStatus(user){let license=user?.user_metadata?.luar_lifetime_license;if(!license)return false;try{let response=await fetch('/api/verify-lifetime',{method:'POST',headers:await sessionHeaders(),body:JSON.stringify({license})}),result=await response.json();return!!result.lifetime}catch{return false}}
function ensureAccountCard(){let grid=document.getElementById('settingsAccountGrid');if(!grid||grid.querySelector('.account-card'))return;let email=currentUser?.email||'Conta ainda não conectada',initial=(state.profile.name||currentUser?.user_metadata?.name||'LU').slice(0,2).toUpperCase(),colors=['#32ff7e','#64b5ff','#b68cff','#ff8a5b','#ffd463'];grid.insertAdjacentHTML('afterbegin',`<article class="card settings-card account-card"><span>CONTA LUAR</span><h3>${lifetimeActive?'Sincronização Vitalícia ativa':'Dados salvos neste dispositivo'}</h3><div class="account-user"><i>${safe(initial)}</i><b>${safe(state.profile.name||'Seu perfil')}<small>${safe(email)}</small></b></div><label>Seu estado<select class="state-select" id="accountState"><option value="">Selecione</option>${stateOptions(state.profile.state)}</select></label><p>${lifetimeActive?'✓ Seus dados são sincronizados com segurança na nuvem.':'🔒 Sincronização em nuvem disponível no LUAR Vitalício.'}</p><button class="secondary signout-button" id="signOutBtn">Sair da conta</button></article><article class="card settings-card appearance-card"><span>APARÊNCIA VITALÍCIA</span><h3>Escolha a cor da sua órbita</h3><p>O verde LUAR é gratuito. Outras cores e a personalização são exclusivas do Vitalício.</p><div class="color-presets">${colors.map((color,index)=>`<button class="color-choice ${index?'locked':''}" style="--choice:${color}" data-color="${color}" aria-label="Usar cor ${color}"></button>`).join('')}</div><div class="custom-color-row"><input id="customAccent" type="color" value="${safe(state.profile.accent||'#32ff7e')}"><button class="secondary" id="applyCustomAccent">Aplicar cor personalizada 🔒</button></div></article>`);document.getElementById('signOutBtn').onclick=async()=>{await supabaseClient?.auth.signOut();currentUser=null;loadedUserId=null;lifetimeActive=false;state=structuredClone(EMPTY);applyAccent();buildPages();render();showLanding()};document.getElementById('accountState').onchange=e=>{state.profile.state=e.target.value;writeLocalState();scheduleCloudSave();renderBigAgenda();toast('Estado atualizado',e.target.value?`Calendário preparado para ${e.target.value}.`:'Seleção de estado removida.')};document.querySelectorAll('.color-choice').forEach((button,index)=>button.onclick=()=>{if(!lifetimeActive&&index>0)return showPremiumGate('Cores exclusivas','Personalize toda a luz do LUAR com qualquer cor ao ativar o plano Vitalício.');state.profile.accent=button.dataset.color;writeLocalState();scheduleCloudSave();applyPremiumUI();toast('Cor atualizada','A nova cor foi aplicada ao LUAR.')});document.getElementById('applyCustomAccent').onclick=()=>{if(!lifetimeActive)return showPremiumGate('Cor personalizada','Crie uma identidade visual exclusiva com o LUAR Vitalício.');state.profile.accent=document.getElementById('customAccent').value;writeLocalState();scheduleCloudSave();applyPremiumUI();toast('Cor personalizada aplicada','Sua órbita ganhou uma nova luz.')}}
