function setPaymentView(mode,message=''){document.getElementById('paymentBenefits').style.display='none';document.getElementById('paymentLoading').style.display=mode==='loading'?'grid':'none';document.getElementById('paymentPix').classList.toggle('show',mode==='pix');let status=document.getElementById('paymentStatus');status.textContent=message;status.className=`payment-status ${mode==='error'?'error':mode==='paid'?'paid':''}`}
