async function startLifetimeCheckout(){if(!currentUser){upgradeAfterAuth=true;closePayment();openAuth('signup');authMessage('Crie ou entre na sua conta para vincular o Vitalício com segurança.',true);return}setPaymentView('loading');try{if(currentPayment?.id&&currentPayment?.checkoutToken)return displayPayment(currentPayment);let response=await fetch('/api/create-lifetime-payment',{method:'POST',headers:await sessionHeaders(),body:'{}'}),result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível gerar o Pix.');displayPayment(result)}catch(error){setPaymentView('error',error.message)}}
async function checkLifetimePayment(){if(!currentPayment?.id)return;let button=document.getElementById('checkPayment');button.disabled=true;button.textContent='Verificando…';try{let response=await fetch('/api/check-lifetime-payment',{method:'POST',headers:await sessionHeaders(),body:JSON.stringify({id:currentPayment.id,checkoutToken:currentPayment.checkoutToken})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível verificar.');if(!result.paid){setPaymentView('pix','Pagamento ainda não identificado. Aguarde alguns segundos e tente novamente.');return}let metadata={...(currentUser.user_metadata||{}),luar_lifetime_license:result.license,luar_plan:'lifetime'};let{data,error}=await supabaseClient.auth.updateUser({data:metadata});if(error)throw error;currentUser=data.user;lifetimeActive=true;localStorage.removeItem(paymentStorageKey());clearInterval(paymentPoll);paymentPoll=null;setPaymentView('paid','✓ Pagamento confirmado! O LUAR Vitalício já está ativo nesta conta.');applyAccent();buildPages();render();await pushCloudState();setTimeout(closePayment,1800);toast('Bem-vindo ao LUAR Vitalício','Todos os limites e recursos premium foram desbloqueados.')}catch(error){setPaymentView('error',error.message)}finally{button.disabled=false;button.textContent='Já paguei, verificar'}}
