document.getElementById('upgradeBtn').onclick=openUpgrade;document.addEventListener('click',e=>{if(e.target.closest('[data-upgrade]')){e.preventDefault();document.getElementById('backdrop').classList.remove('open');openUpgrade()}if(!lifetimeActive&&e.target.closest('.agenda-year-card[data-premium-locked="true"]'))showPremiumGate('Calendário anual','A visão anual completa e os feriados estaduais são exclusivos do LUAR Vitalício.');if(!lifetimeActive&&e.target.closest('#investmentMarket[data-premium-locked="true"]'))showPremiumGate('Mercado e exploração de ativos','Pesquise cotações e acompanhe ativos nacionais e internacionais com o LUAR Vitalício.')});document.getElementById('paymentClose').onclick=closePayment;document.getElementById('paymentLayer').onclick=e=>{if(e.target.id==='paymentLayer')closePayment()};document.getElementById('startPayment').onclick=startLifetimeCheckout;document.getElementById('copyPayment').onclick=async()=>{await navigator.clipboard.writeText(document.getElementById('paymentCode').value);toast('Código Pix copiado','Agora cole no aplicativo do seu banco.')};document.getElementById('checkPayment').onclick=checkLifetimePayment;
