function authCopy(mode){return{login:['BEM-VINDO DE VOLTA','Entrar no LUAR','Use seu e-mail e senha para continuar.','Entrar','Ainda não tem uma conta?', 'Criar conta'],signup:['CRIE SUA ÓRBITA','Começar no LUAR','Sua jornada fica protegida e disponível na sua conta.','Criar minha conta','Já possui uma conta?','Entrar'],recovery:['RECUPERAÇÃO DE SENHA','Recuperar acesso','Enviaremos um link seguro para o seu e-mail.','Enviar link','Lembrou sua senha?','Entrar'],update:['NOVA SENHA','Proteja sua conta','Escolha uma nova senha com pelo menos 6 caracteres.','Salvar nova senha','', '']}[mode]}
function setAuthMode(mode='login'){authMode=mode;let card=document.querySelector('.auth-card'),copy=authCopy(mode);card.dataset.mode=mode;document.getElementById('authKicker').textContent=copy[0];document.getElementById('authTitle').textContent=copy[1];document.getElementById('authSubtitle').textContent=copy[2];card.querySelector('.auth-submit').textContent=copy[3];document.getElementById('authSwitch').innerHTML=copy[4]?`${copy[4]} <button data-auth-mode="${mode==='login'?'signup':'login'}">${copy[5]}</button>`:'';card.querySelector('[name="name"]').required=mode==='signup';card.querySelector('[name="state"]').required=mode==='signup';card.querySelector('[name="password"]').required=!['recovery'].includes(mode);card.querySelector('[name="password"]').autocomplete=mode==='update'?'new-password':mode==='signup'?'new-password':'current-password';document.getElementById('authStatus').textContent=''}
