async function handleSignedIn(user){if(!user||loadedUserId===user.id){if(user)enterApp();return}currentUser=user;loadedUserId=user.id;lifetimeActive=await verifyLifetimeStatus(user);let remote=lifetimeActive?user.user_metadata?.luar_state:null,accountLocal=(()=>{try{return JSON.parse(localStorage.getItem(`luar-state:${user.id}`))}catch{return null}})(),legacy=(()=>{try{return JSON.parse(localStorage.getItem('luar-state'))}catch{return null}})(),chosen=remote||accountLocal||legacy||structuredClone(EMPTY);applyAccountState(chosen);if(!state.profile.name)state.profile.name=user.user_metadata?.name||user.email?.split('@')[0]||'';if(!state.profile.state)state.profile.state=user.user_metadata?.state||'';financeLineMode=lifetimeActive&&state.profile.financeLineMode==='separate'?'separate':'combined';writeLocalState();buildPages();render();enterApp();if(lifetimeActive&&!remote&&stateHasContent(state))scheduleCloudSave();if(!state.profile.state)setTimeout(openStateSetup,500);if(upgradeAfterAuth){upgradeAfterAuth=false;setTimeout(openUpgrade,450)}}
document.querySelectorAll('[data-auth-open]').forEach(button=>button.onclick=()=>currentUser?enterApp():openAuth(button.dataset.authOpen));
document.getElementById('authClose').onclick=()=>document.getElementById('authLayer').classList.remove('open');
document.getElementById('authLayer').onclick=e=>{if(e.target.id==='authLayer')e.currentTarget.classList.remove('open')};
