document.getElementById('authStatus').onclick=e=>{let button=e.target.closest('[data-auth-mode]');if(button)setAuthMode(button.dataset.authMode)};
document.getElementById('authForm').onsubmit=async e=>{e.preventDefault();if(!supabaseClient){authMessage('A conexão de conta ainda não está disponível.');return}let form=new FormData(e.target),email=String(form.get('email')||'').trim(),password=String(form.get('password')||''),name=String(form.get('name')||'').trim(),userState=String(form.get('state')||''),submit=e.target.querySelector('.auth-submit');submit.disabled=true;submit.textContent='Aguarde…';try{if(authMode==='login'){let{data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;await handleSignedIn(data.user)}else if(authMode==='signup'){let{data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{name,state:userState},emailRedirectTo:`${location.origin}${location.pathname}`}});if(error)throw error;if(data.user&&Array.isArray(data.user.identities)&&!data.user.identities.length){authMessage('Este e-mail já possui uma conta no LUAR.',false,true);return}if(data.session)await handleSignedIn(data.user);else authMessage('Conta criada. Confirme o link enviado ao seu e-mail.',true)}else if(authMode==='recovery'){let{error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:`${location.origin}${location.pathname}#reset-password`});if(error)throw error;authMessage('Link de recuperação enviado. Confira seu e-mail.',true)}else if(authMode==='update'){let{error}=await supabaseClient.auth.updateUser({password});if(error)throw error;authMessage('Senha atualizada com sucesso.',true);setTimeout(()=>enterApp(),900)}}catch(error){let registered=/already registered|already been registered|user already exists/i.test(error.message),message=/invalid login/i.test(error.message)?'E-mail ou senha incorretos.':registered?'Este e-mail já possui uma conta no LUAR.':error.message;authMessage(message,false,registered)}finally{submit.disabled=false;submit.textContent=authCopy(authMode)[3]}};
if(supabaseClient){supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){currentUser=session?.user||null;openAuth('update');return}if(event==='SIGNED_OUT'){currentUser=null;loadedUserId=null;lifetimeActive=false;applyAccent();showLanding();return}if(session?.user)setTimeout(()=>handleSignedIn(session.user),0);else if(event==='INITIAL_SESSION')showLanding()});supabaseClient.auth.getSession().then(({data})=>data.session?.user?handleSignedIn(data.session.user):showLanding())}else showLanding();

buildPages();render();chartHover();rt();if(location.hash&&document.getElementById(location.hash.slice(1))){showPage(location.hash.slice(1));requestAnimationFrame(()=>scrollTo(0,0));setTimeout(()=>scrollTo(0,0),80)}
